function icon(name) { return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name] || iconPaths.products}</svg>`; }
// 所有放进 HTML 的数据先转义，商品名、用户昵称等不能被当成脚本执行。
function esc(value) { return String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char])); }
function num(value) { const number = Number(value); return Number.isFinite(number) ? number : 0; }
function money(value) { return num(value).toFixed(2); }
function integer(value) { return Math.trunc(num(value)).toLocaleString('zh-CN'); }
function dateTime(value, short = false) { if (!value) return '—'; const date = new Date(value); if (Number.isNaN(date.getTime())) return esc(String(value).replace('T', ' ').slice(0, short ? 10 : 19)); return date.toLocaleString('zh-CN', short ? { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false } : { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }); }
function enabled(value) { return value === true || value === 1 || value === 'true'; }
function array(value) { return Array.isArray(value) ? value : []; }
