function levelFor(user) { const spent = num(user.totalSpent); return user.level || (spent >= 30000 ? '黑金会员' : spent >= 15000 ? '金卡会员' : spent >= 5000 ? '银卡会员' : '普通会员'); }
function discountText(rate) { const n = num(rate || 1); return n >= 1 ? '标准价格' : `${(n * 10).toFixed(1).replace(/\.0$/, '')} 折`; }
function statusTag(status) { const style = ['REFUNDED', 'CANCELLED'].includes(status) ? 'gray' : status === 'FAILED' ? 'red' : ['WAITING', 'PROCESSING', 'BUSY'].includes(status) ? 'orange' : ''; return `<span class="tag ${style}"><span class="dot"></span>${esc(statusNames[status] || status)}</span>`; }
function empty(title = '这里还没有记录', detail = '完成销售、采购或会员业务后，记录会显示在这里。', emoji = '💻') { return `<div class="empty"><span class="empty-icon">${emoji}</span><strong>${esc(title)}</strong><span class="small">${esc(detail)}</span></div>`; }
