async function fetchCsrf() { const response = await fetch('/api/auth/csrf', { credentials: 'same-origin', cache: 'no-store' }); const result = await response.json(); if (!response.ok || !result.success) throw new Error(result.message || '无法获取安全令牌，请刷新页面'); state.csrf = result.data; }
async function api(path, method = 'GET', body, options = {}) {
  const headers = { Accept: 'application/json' };
  if (method !== 'GET') { if (!state.csrf) await fetchCsrf(); headers[state.csrf.headerName || 'X-CSRF-TOKEN'] = state.csrf.token; }
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  let response;
  try { response = await fetch(`/api${path}`, { method, headers, credentials: 'same-origin', cache: 'no-store', body: body === undefined ? undefined : JSON.stringify(body), signal: options.signal }); }
  catch (error) { if (error.name === 'AbortError') throw error; throw new Error('暂时无法连接门店，请确认 Java 程序正在运行'); }
  const contentType = response.headers.get('content-type') || '';
  const result = contentType.includes('json') ? await response.json() : { success: false, message: `服务返回异常（${response.status}）` };
  if (!response.ok || result.success === false) {
    const error = new Error(result.message || `请求未完成（${response.status}）`); error.status = response.status;
    if (response.status === 401 && state.user) { resetSession(); renderAuth('登录已过期，请重新登录'); }
    throw error;
  }
  return result.data;
}

