async function loadCatalog() {
  const query = new URLSearchParams(); if (state.keyword) query.set('keyword', state.keyword); if (state.categoryId) query.set('categoryId', state.categoryId);
  const [categories, products] = await Promise.all([api('/categories'), api(`/products?${query}`)]); state.categories = array(categories); state.products = array(products);
  if (isMember()) state.cart = array(await api('/cart'));
  if (state.page === 'pos') {
    state.members = array(await api('/users')).filter(user => user.role === 'MEMBER' && enabled(user.enabled));
    if (state.selectedMember && !state.members.some(member => String(member.id) === state.selectedMember)) state.selectedMember = '';
  }
}

