function displayUserName(user) { return user?.username === 'admin' && user?.displayName === '乔胤淇' ? '乔胤淇（乔先生）' : user?.displayName || user?.username || ''; }

function productCard(product, i) {
  const available = enabled(product.onSale) && num(product.stock) > 0;
  const canBuy = isMember() || state.page === 'pos';
  return `<article class="product-card"><div class="product-visual tone${i % 4}"><span class="tag">${esc(product.categoryName || '数码设备')}</span>${!enabled(product.onSale) ? '<span class="tag gray" style="left:auto;right:12px">已下架</span>' : ''}${deviceArtwork(product)}</div><div class="product-card-body"><div class="product-category">${esc(product.sku || 'JIXU DIGITAL SELECTED')}</div><h3>${esc(product.name)}</h3><p class="product-description">${esc(product.description || '设备型号、规格与库存以门店资料为准。')}</p><div class="product-bottom"><div class="price"><small>¥</small>${money(product.price)}</div>${canBuy ? `<button class="add-button" data-action="add-basket" data-id="${num(product.id)}" title="加入购物车" aria-label="加入 ${esc(product.name)}" ${!available ? 'disabled' : ''}>${icon('plus')}</button>` : ''}</div><div class="stock-note ${num(product.stock) <= num(product.lowStockThreshold) ? 'low' : ''}"><span class="dot"></span>${num(product.stock) <= 0 ? '暂时售罄，等待补货' : `库存 ${integer(product.stock)} 件${num(product.stock) <= num(product.lowStockThreshold) ? ' · 即将售罄' : ' · 现货供应'}`}</div></div>${isAdmin() && state.page !== 'pos' ? `<div class="product-manage"><button class="btn tiny" data-action="product-edit" data-id="${num(product.id)}">${icon('edit').replace('class="icon"', 'class="icon" style="width:12px;height:12px"')}编辑</button><button class="btn tiny outline" data-action="product-sale" data-id="${num(product.id)}">${enabled(product.onSale) ? '下架' : '上架'}</button><button class="icon-btn danger" title="删除商品" aria-label="删除商品" data-action="product-delete" data-id="${num(product.id)}">${icon('trash').replace('class="icon"', 'class="icon" style="width:15px;height:15px"')}</button></div>` : ''}</article>`;
}
function basketItems() { return isMember() ? state.cart : state.basket.map(item => { const product = state.products.find(product => num(product.id) === num(item.productId)); return { ...item, ...product, productId: item.productId, name: product?.name || item.name, price: product?.price ?? item.price, stock: product?.stock ?? item.stock, emoji: product?.emoji ?? item.emoji }; }); }
function basketPanel() {
  const items = basketItems(), total = items.reduce((sum, item) => sum + num(item.price) * num(item.quantity), 0), quantity = items.reduce((sum, item) => sum + num(item.quantity), 0);
  return `<aside class="panel basket-panel"><div class="panel-head"><div><h2>${isMember() ? '我的购物车' : '本次收银'}</h2><p>${quantity} 件设备，准备带走</p></div><span class="tag">${isMember() ? '会员购物' : '模拟支付'}</span></div>${items.length ? `<div class="basket-list">${items.map(item => `<div class="basket-row"><div class="basket-emoji">${esc(item.emoji || '📦')}</div><div class="basket-info"><strong>${esc(item.name)}</strong><div class="basket-price">¥${money(item.price)} / 件</div></div><div class="quantity"><button data-action="basket-minus" data-id="${num(item.productId)}" aria-label="减少数量">−</button><span>${integer(item.quantity)}</span><button data-action="basket-plus" data-id="${num(item.productId)}" aria-label="增加数量">+</button></div></div>`).join('')}</div>` : empty('购物车还是空的', '点击商品旁的 +，加入喜欢的设备。', '🛍️')}${!isMember() ? `<div class="basket-member"><label class="field"><span>顾客身份</span><select id="pos-member"><option value="">到店散客 · 无会员折扣</option>${state.members.map(member => `<option value="${num(member.id)}" ${String(member.id) === state.selectedMember ? 'selected' : ''}>${esc(member.displayName || member.username)} · ${esc(member.username)} · ${esc(levelFor(member))}</option>`).join('')}</select></label></div>` : ''}<div class="basket-summary"><div class="summary-line"><span>商品原价</span><span class="amount">¥${money(total)}</span></div><div class="summary-line"><span>优惠与会员权益</span><span>确认结账时自动计算</span></div><div class="summary-total"><span>原价小计</span><span class="amount">¥${money(total)}</span></div><button class="btn primary full" data-action="preview-checkout" ${!items.length ? 'disabled' : ''}>${isMember() ? '查看优惠并排队结账' : '确认商品与收款'}${icon('arrow')}</button><p class="basket-tip">${isMember() ? '提交后显示指定收银台，等待对应收银员确认模拟支付。' : '支付为课程演示，不会发起任何真实扣款。'}</p>${!isMember() && items.length ? '<button class="btn link full small" data-action="clear-basket">清空本次收银</button>' : ''}</div></aside>`;
}
async function viewCatalog() {
  await loadCatalog(); const isPos = state.page === 'pos', showBasket = isMember() || isPos;
  return heading(isPos ? '到店销售 · 手动开单' : isMember() ? '数码装备，按需选择' : '数码产品与型号管理', isPos ? '为现场顾客选择商品、会员与数量，确认优惠后完成销售。' : isMember() ? '从移动办公到电竞创作，选择适合你的设备。' : '管理商品信息与上下架，库存通过采购与销售自动流转。', isAdmin() && !isPos ? `<button class="btn outline" data-action="category-manage">分类管理</button><button class="btn primary" data-action="product-new">${icon('plus')}新增商品</button>` : '', isMember() ? 'DEVICES / FIND YOUR NEXT UPGRADE' : 'JIXU DIGITAL / PRODUCT & SALES') + `<form class="toolbar" id="catalog-search"><div class="search">${icon('search')}<input name="keyword" placeholder="搜索设备名称、型号或 SKU…" value="${esc(state.keyword)}" maxlength="80"></div><button class="btn outline" type="submit">搜索设备</button>${state.keyword ? '<button class="btn link" type="button" data-action="clear-search">清除搜索</button>' : ''}<span class="small muted" style="margin-left:auto">共 ${state.products.length} 件商品</span></form><div class="category-pills"><button class="pill ${!state.categoryId ? 'active' : ''}" data-action="category-filter" data-id="">全部设备</button>${state.categories.map(category => `<button class="pill ${String(category.id) === state.categoryId ? 'active' : ''}" data-action="category-filter" data-id="${num(category.id)}">${esc(category.name)}</button>`).join('')}</div><div class="${showBasket ? 'catalog-layout' : ''}"><div>${state.products.length ? `<div class="product-grid">${state.products.map(productCard).join('')}</div>` : `<section class="panel">${empty('没有找到这件设备', '换一个关键词或分类，再找找看。', '🔎')}</section>`}</div>${showBasket ? basketPanel() : ''}</div>`;
}
async function viewCart() { const [cart, me] = await Promise.all([api('/cart'), api('/auth/me')]); state.cart = array(cart); state.user = me; return heading('确认设备，准备升级', '确认数量后提交到指定收银台，等待对应收银员核对并确认结账。', `<button class="btn outline" data-action="navigate" data-page="catalog">继续选购 ${icon('arrow')}</button>`, 'MY CART / YOUR NEXT UPGRADE') + `<div class="grid-two"><section class="panel"><div class="panel-head"><h2>购物车清单</h2><span class="tag">${state.cart.length} 种设备</span></div>${state.cart.length ? `<div class="table-wrap"><table><thead><tr><th>商品</th><th>单价</th><th>数量</th><th>小计</th><th></th></tr></thead><tbody>${state.cart.map(item => `<tr><td><div class="table-main"><div class="table-emoji">${esc(item.emoji || '📦')}</div><div><strong>${esc(item.name)}</strong><div class="table-sub">库存 ${integer(item.stock)} 件${!enabled(item.onSale) ? ' · 已下架' : ''}</div></div></div></td><td class="amount">¥${money(item.price)}</td><td><div class="quantity"><button data-action="basket-minus" data-id="${num(item.productId)}">−</button><span>${integer(item.quantity)}</span><button data-action="basket-plus" data-id="${num(item.productId)}">+</button></div></td><td class="amount">¥${money(num(item.price) * num(item.quantity))}</td><td><button class="icon-btn danger" data-action="cart-remove" data-id="${num(item.productId)}" aria-label="移除商品">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div>` : empty('购物车还是空的', '去商品页挑几件喜欢的设备吧。', '🛍️')}</section><div>${basketPanel()}<div class="callout section-gap">${icon('star')}<p>当前等级：<strong>${esc(levelName(me.level))}</strong>，享受 ${discountText(me.discountRate)}。积分按实付金额向下取整获得，整单退款时会撤回对应积分。</p></div></div></div>`; }

async function viewOrders() {
  const orders = array(await api('/orders')); state.orders = orders;
  return heading(isMember() ? '设备订单与购买记录' : '销售订单与售后管理', isMember() ? '查看订单明细、优惠和支付记录，售后可联系门店工作人员。' : isAdmin() ? '查看全店订单、销售归属与整单退货退款。' : '这里只显示你经手的订单，你可以为这些订单办理整单退款。', `<button class="btn outline" data-action="refresh">${icon('refresh')}刷新订单</button>`) + `<section class="panel"><div class="panel-head"><h2>${isMember() ? '我的订单' : '订单记录'}</h2><span class="small muted">共 ${orders.length} 笔</span></div>${orders.length ? `<div class="table-wrap"><table><thead><tr><th>订单编号 / 时间</th><th>顾客</th><th>商品原价</th><th>优惠</th><th>实付金额</th><th>收银员</th><th>状态</th><th>操作</th></tr></thead><tbody>${orders.map(order => `<tr><td><strong class="mono">${esc(order.orderNo)}</strong><div class="table-sub">${dateTime(order.createdAt)}</div></td><td>${esc(order.memberName || '到店散客')}</td><td class="amount">¥${money(order.originalAmount)}</td><td class="primary-text">− ¥${money(num(order.originalAmount) - num(order.payableAmount))}</td><td class="amount">¥${money(order.payableAmount)}</td><td>${esc(order.cashierName || '—')}</td><td>${statusTag(order.status)}</td><td><div class="table-actions"><button class="btn tiny" data-action="order-detail" data-id="${num(order.id)}">查看详情</button>${refundActions(order)}</div></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>订单金额与状态以数据库记录为准</span><span>退款后库存与会员权益一并回退</span></div>` : empty('还没有订单记录', isMember() ? '选购设备并完成排队结账后，就能在这里找到它。' : '开始一笔收银，订单会自动保存在这里。', '🧾')}</section>`;
}
function queueLive(data) {
  const counters = array(data.counters), tickets = array(data.tickets);
  return `<div class="queue-toolbar"><div class="queue-status"><span><strong>${integer(data.waitingCount)}</strong>${isAdmin() ? '笔等待确认' : isMember() ? '笔等待中' : '笔待本人确认'}</span><span><strong>${integer(data.processingCount)}</strong>笔结账中</span></div><span class="tag" id="queue-connection"><span class="dot"></span>看板每 2 秒自动更新</span></div><div class="counter-grid">${counters.map(counter => { const busy = ['BUSY', 'PROCESSING', 'RUNNING', 'WAITING'].includes(counter.status); return `<div class="counter-card ${busy ? 'busy' : ''}"><div class="counter-id">CHECKOUT COUNTER ${String(num(counter.counterNo)).padStart(2, '0')}</div><div class="counter-icon">${busy ? '🛍️' : '🧾'}</div><h3>${integer(counter.counterNo)} 号收银台</h3><p class="counter-cashier"><strong>${esc(counter.cashierName || '待安排收银员')}</strong>${counter.cashierUsername ? `<small>账号 ${esc(counter.cashierUsername)}</small>` : ''}</p><div class="counter-status">${statusTag(counter.status)}</div><p class="counter-waiting">${num(counter.waitingCount) ? `${integer(counter.waitingCount)} 笔等待确认` : '暂无待确认商品'}</p></div>`; }).join('') || '<div class="callout">收银台尚未开启，请联系店长检查设置。</div>'}</div><section class="panel"><div class="panel-head"><div><h2>${isMember() ? '我的提交记录' : isAdmin() ? '全店会员提交记录' : '分配给我的会员提交'}</h2><p>${isMember() ? '提交后等待对应收银员在工作台确认结账' : isAdmin() ? '每笔提交已指定收银台，由对应收银员确认结账' : '仅显示本人收银台的记录，请到收银工作台核对商品并确认'}</p></div><button class="btn link" data-action="queue-refresh">${icon('refresh')}刷新</button></div>${tickets.length ? `<div class="table-wrap"><table><thead><tr><th>票号</th><th>顾客</th><th>提交时间</th><th>收银台 / 收银员</th><th>状态</th><th>说明 / 操作</th></tr></thead><tbody>${tickets.map(ticket => `<tr><td><strong class="mono">Q${String(num(ticket.id)).padStart(5, '0')}</strong></td><td>${esc(ticket.memberName || '会员')}</td><td>${dateTime(ticket.createdAt, true)}</td><td>${ticket.counterNo ? `${integer(ticket.counterNo)} 号收银台` : '历史记录'}<div class="table-sub">${esc(ticket.cashierName || '—')}${ticket.cashierUsername ? ` · ${esc(ticket.cashierUsername)}` : ''}</div></td><td>${statusTag(ticket.status)}</td><td>${ticket.errorMessage ? `<span class="danger-text small">${esc(ticket.errorMessage)}</span>` : ticket.orderId ? `<button class="btn tiny" data-action="order-detail" data-id="${num(ticket.orderId)}">查看订单</button>` : ticket.status === 'WAITING' && isMember() ? `<button class="btn tiny outline" data-action="queue-cancel" data-id="${num(ticket.id)}">取消提交</button>` : ticket.status === 'WAITING' && !isAdmin() ? '<button class="btn tiny outline" data-action="navigate" data-page="pos">去工作台确认</button>' : '<span class="small muted">等待对应收银员确认</span>'}</td></tr>`).join('')}</tbody></table></div>` : empty('暂无会员提交', isMember() ? '在购物车提交设备，即可分配收银台。' : '会员提交后，会分配到已安排员工的收银台。', '💠')}</section>`;
}
async function viewQueue() {
  const data = await api('/queue');
  state.queueFingerprint = queueFingerprint(data);
  return heading(isAdmin() ? '排队管理' : '排队结账，实时查看进度', '查看各收银台的负责员工和等待进度，由对应收银员在工作台确认结账。', isMember() ? `<button class="btn primary" data-action="navigate" data-page="cart">${icon('cart')}查看我的购物车</button>` : isAdmin() ? `<button class="btn primary" data-action="navigate" data-page="cashiers">${icon('users')}安排收银员</button>` : '', 'CHECKOUT QUEUE / LIVE STATUS') + `<div id="queue-live">${queueLive(data)}</div>`;
}
function queueFingerprint(data) { return array(data.tickets).map(ticket => `${ticket.id}:${ticket.status}`).join('|'); }
function startQueuePoll() {
  const version = state.routeVersion;
  state.queueTimer = setInterval(async () => {
    // 前一次轮询尚未返回时不重叠请求；切换页面后也不回写旧请求的结果。
    if (state.queuePolling || state.page !== 'queue' || document.hidden || !state.user) return;
    state.queuePolling = true;
    try {
      const data = await api('/queue', 'GET', undefined, { quiet: true });
      if (version !== state.routeVersion || state.page !== 'queue' || !$('#queue-live')) return;
      const fingerprint = queueFingerprint(data);
      if (isMember() && fingerprint !== state.queueFingerprint) {
        const [cart, me] = await Promise.all([api('/cart'), api('/auth/me')]);
        if (version !== state.routeVersion || !state.user) return;
        state.cart = array(cart); state.user = me; updateCartBadge();
      }
      state.queueFingerprint = fingerprint;
      $('#queue-live').innerHTML = queueLive(data);
    } catch (error) {
      if (version !== state.routeVersion) return;
      const connection = $('#queue-connection');
      if (connection) { connection.className = 'tag orange'; connection.textContent = '连接暂时中断，正在重试…'; }
    } finally { state.queuePolling = false; }
  }, 2000);
}
async function viewProcurement() {
  const [suppliers, purchases, products] = await Promise.all([api('/suppliers'), api('/purchases'), api('/products')]); state.suppliers = array(suppliers); state.purchases = array(purchases); state.purchaseProducts = array(products);
  return heading('设备采购与供应链管理', '供应商、采购单和入库数量，都在这里有据可查。', `<button class="btn outline" data-action="supplier-new">${icon('plus')}新增供应商</button><button class="btn primary" data-action="purchase-new">${icon('procurement')}采购入库</button>`) + `<section class="panel"><div class="panel-head"><div><h2>门店的供应商</h2><p>数码设备与配件的采购来源</p></div><span class="tag">${state.suppliers.length} 位伙伴</span></div>${state.suppliers.length ? `<div class="table-wrap"><table><thead><tr><th>供应商名称</th><th>联系人</th><th>联系电话</th><th>操作</th></tr></thead><tbody>${state.suppliers.map(supplier => `<tr><td><div class="table-main"><div class="table-emoji">🚚</div><strong>${esc(supplier.name)}</strong></div></td><td>${esc(supplier.contact || '—')}</td><td class="mono">${esc(supplier.phone || '—')}</td><td><div class="table-actions"><button class="btn tiny" data-action="supplier-edit" data-id="${num(supplier.id)}">编辑资料</button><button class="btn tiny danger" data-action="supplier-delete" data-id="${num(supplier.id)}">删除</button></div></td></tr>`).join('')}</tbody></table></div>` : empty('还没有供应商', '新增供应商后，即可创建采购入库单。', '🚚')}</section><section class="panel section-gap"><div class="panel-head"><div><h2>采购入库记录</h2><p>提交后自动增加商品库存，并生成库存流水</p></div><span class="small muted">共 ${state.purchases.length} 笔</span></div>${state.purchases.length ? `<div class="table-wrap"><table><thead><tr><th>采购编号 / 时间</th><th>供应商</th><th>采购明细</th><th>采购金额</th><th>经办人</th></tr></thead><tbody>${state.purchases.map(purchase => `<tr><td><strong class="mono">P${String(num(purchase.id)).padStart(6, '0')}</strong><div class="table-sub">${dateTime(purchase.createdAt)}</div></td><td>${esc(purchase.supplierName || state.suppliers.find(supplier => num(supplier.id) === num(purchase.supplierId))?.name || '—')}</td><td>${array(purchase.items).map(item => `${esc(item.productName || item.name || `商品 #${item.productId}`)} × ${integer(item.quantity)}`).join('<br>') || '—'}</td><td class="amount">¥${money(purchase.totalAmount)}</td><td>${esc(purchase.operatorName || '—')}</td></tr>`).join('')}</tbody></table></div>` : empty('采购单还是空的', '选择供应商和商品，创建第一张采购单。', '📦')}</section>`;
}
async function viewInventory() { const logs = array(await api('/inventory')); return heading('设备库存，全程可追溯', '采购、销售、退款自动记账，追溯商品数量的每一次变化。', `<button class="btn outline" data-action="refresh">${icon('refresh')}刷新流水</button>`) + `<section class="panel"><div class="panel-head"><h2>库存变动流水</h2><span class="small muted">共 ${logs.length} 条</span></div>${logs.length ? `<div class="table-wrap"><table><thead><tr><th>商品</th><th>业务类型</th><th>变动数量</th><th>变动后库存</th><th>关联单号</th><th>经办人 / 时间</th><th>备注</th></tr></thead><tbody>${logs.map(row => `<tr><td><strong>${esc(row.productName || `商品 #${row.productId}`)}</strong></td><td><span class="tag ${num(row.changeQty) < 0 ? 'orange' : ''}">${esc(inventoryNames[row.type] || row.type)}</span></td><td class="amount ${num(row.changeQty) >= 0 ? 'positive' : 'danger-text'}">${num(row.changeQty) > 0 ? '+' : ''}${integer(row.changeQty)}</td><td class="amount">${integer(row.stockAfter)}</td><td class="mono small">${esc(row.referenceNo || '—')}</td><td>${esc(row.operatorName || '系统')}<div class="table-sub">${dateTime(row.createdAt)}</div></td><td class="small">${esc(row.remark || '—')}</td></tr>`).join('')}</tbody></table></div>` : empty('库存暂时没有变动', '采购或结账后，系统会自动留下库存记录。', '📦')}</section>`; }
async function viewUsers() { const users = array(await api('/users')); state.users = users; return heading('会员与员工账号管理', '管理会员与门店员工，密码原文和哈希都不会在这里显示。', `<button class="btn outline" data-action="refresh">${icon('refresh')}刷新名单</button><button class="btn primary" data-action="navigate" data-page="cashiers">收银员管理</button>`) + `<section class="panel"><div class="panel-head"><h2>会员与门店员工</h2><span class="tag">${users.length} 个账号</span></div><div class="table-wrap"><table><thead><tr><th>昵称 / 账号</th><th>身份</th><th>会员等级</th><th>积分</th><th>累计净消费</th><th>状态</th><th>操作</th></tr></thead><tbody>${users.map(user => `<tr><td><div class="table-main"><div class="avatar">${esc((user.displayName || user.username || '友').slice(0, 1))}</div><div><strong>${esc(user.displayName || user.username)}</strong><div class="table-sub mono">${esc(user.username)}</div></div></div></td><td>${esc(roleNames[user.role] || user.role)}</td><td>${user.role === 'MEMBER' ? `<span class="tag">${esc(levelFor(user))}</span>` : '—'}</td><td class="amount">${integer(user.points)}</td><td class="amount">¥${money(user.totalSpent)}</td><td><span class="tag ${enabled(user.enabled) ? '' : 'gray'}">${enabled(user.enabled) ? '正常使用' : '已停用'}</span></td><td>${num(user.id) === num(state.user.id) ? '<span class="small muted">当前账号</span>' : `<button class="btn tiny ${enabled(user.enabled) ? 'outline' : ''}" data-action="user-toggle" data-id="${num(user.id)}">${enabled(user.enabled) ? '停用账号' : '恢复使用'}</button>`}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>新会员可在登录页自行注册</span><span>账号停用后将无法继续办理业务</span></div></section>`; }
async function viewSettings() { const settings = await api('/settings'); state.settings = settings; return heading('促销与会员权益配置', '普通优惠、会员折扣与满减按顺序计算，结账时统一确认。') + `<div class="grid-equal"><section class="panel settings-card"><h3>门店优惠与收银配置</h3><p>修改后对后续结账生效，已有订单保留当时的价格快照。</p><form id="settings-form"><div class="form-grid single-mobile"><label class="field"><span>全场商品折扣率</span><input name="productDiscountRate" type="number" required min="0.10" max="1" step="0.01" value="${num(settings.productDiscountRate) || 1}"><small>1.00 为原价，0.90 为九折</small></label><label class="field"><span>开放前几个收银台</span><select name="counterCount">${[1, 2, 3, 4].map(value => `<option value="${value}" ${num(settings.counterCount) === value ? 'selected' : ''}>开放 1 至 ${value} 号台</option>`).join('')}</select><small>仅已绑定启用收银员的柜台接收新提交；已有提交仍由原收银员处理</small></label><label class="field"><span>满减门槛（元）</span><input name="fullReductionThreshold" type="number" required min="0.01" max="999999" step="0.01" value="${num(settings.fullReductionThreshold)}"><small>在普通优惠、会员折扣之后判断</small></label><label class="field"><span>满减金额（元）</span><input name="fullReductionAmount" type="number" required min="0" max="999999" step="0.01" value="${num(settings.fullReductionAmount)}"><small>填 0 可关闭满减，实付最低为 0</small></label></div><div class="form-actions"><button class="btn primary" type="submit">${icon('check')}保存门店设置</button></div></form></section><section class="panel settings-card"><h3>会员等级与优惠顺序</h3><p>会员等级根据累计净消费自动计算，退款会回退累计消费。</p><div class="table-wrap"><table><thead><tr><th>会员等级</th><th>净消费门槛</th><th>专属折扣</th></tr></thead><tbody><tr><td>普通会员</td><td>¥0</td><td>标准价格</td></tr><tr><td>银卡会员</td><td>¥5,000</td><td>9.8 折</td></tr><tr><td>金卡会员</td><td>¥15,000</td><td>9.5 折</td></tr><tr><td>黑金会员</td><td>¥30,000</td><td>9 折</td></tr></tbody></table></div><div class="discount-example"><strong>一笔订单的优惠旅程</strong><br>商品原价 → 全场商品优惠 → 会员等级折扣 → 折后满减 → 实付金额<br><br>每一步优惠计算均保留两位小数。积分按最终实付金额向下取整，整单退款会撤销该订单积分。</div></section></div>`; }
async function viewLogs() { const rows = array(await api('/audit')); return heading('关键操作，留痕可查', '关键业务操作会留下记录，便于追溯和课堂展示。', `<button class="btn outline" data-action="refresh">${icon('refresh')}刷新日志</button>`) + `<section class="panel"><div class="panel-head"><h2>操作日志</h2><span class="small muted">共 ${rows.length} 条</span></div>${rows.length ? `<div class="table-wrap"><table><thead><tr><th>时间</th><th>操作者</th><th>操作</th><th>详细说明</th></tr></thead><tbody>${rows.map(row => `<tr><td class="nowrap">${dateTime(row.createdAt)}</td><td>${esc(row.operatorName || '系统')}</td><td><span class="tag gray">${esc(row.action)}</span></td><td>${esc(row.detail || '—')}</td></tr>`).join('')}</tbody></table></div>` : empty('还没有操作记录', '商品管理、采购、结账等关键操作会记录在这里。', '📋')}</section>`; }
async function viewPoints() { const [me, logs] = await Promise.all([api('/auth/me'), api('/points')]); state.user = me; const spent = num(me.totalSpent), levels = [['普通会员', 0], ['银卡会员', 5000], ['金卡会员', 15000], ['黑金会员', 30000]], activeLevel = spent >= 30000 ? 3 : spent >= 15000 ? 2 : spent >= 5000 ? 1 : 0; return heading('每次设备升级，积累更多权益', '累计净消费决定会员等级，积分随有效订单增加。', '', 'JIXU DIGITAL / MEMBERSHIP') + `<div class="grid-equal"><div><div class="member-card"><div class="eyebrow">JIXU DIGITAL · MEMBERSHIP</div><h2>${esc(levelName(me.level))}</h2><div class="member-number">${esc(me.displayName)} · NO.${String(num(me.id)).padStart(8, '0')}</div><div class="member-benefit">${discountText(me.discountRate)} 专属折扣</div></div><section class="panel section-gap"><div class="panel-body"><div class="summary-line"><span>当前累计净消费</span><strong class="amount primary-text">¥${money(spent)}</strong></div><div class="level-track">${levels.map(([name, threshold], index) => `<div class="level-step ${index <= activeLevel ? 'active' : ''}"><i>${index <= activeLevel ? '✓' : index + 1}</i>${name}<small>¥${integer(threshold)}</small></div>`).join('')}</div><div class="callout section-gap">${icon('star')}<p>${activeLevel < 3 ? `距离下一等级还差 ¥${money(levels[activeLevel + 1][1] - spent)}，每次消费都更接近一点。` : '你已达到最高会员等级，可享受黑金会员折扣。'}</p></div></div></section></div><section class="panel"><div class="panel-head"><h2>会员积分账本</h2><span class="tag">可用 ${integer(me.points)} 分</span></div>${array(logs).length ? `<div class="table-wrap"><table><thead><tr><th>时间 / 业务</th><th>变动积分</th><th>变动后余额</th></tr></thead><tbody>${array(logs).map(log => `<tr><td>${dateTime(log.createdAt, true)}<div class="table-sub">${esc(log.type === 'REFUND' ? '整单退款，积分撤回' : log.type === 'SALE' || log.type === 'EARN' || log.type === 'PURCHASE' ? '购物获得积分' : log.type)}</div></td><td class="amount ${num(log.changePoints) >= 0 ? 'positive' : 'danger-text'}">${num(log.changePoints) > 0 ? '+' : ''}${integer(log.changePoints)}</td><td class="amount">${integer(log.balanceAfter)}</td></tr>`).join('')}</tbody></table></div>` : empty('暂无积分记录', '完成一笔设备订单即可获得积分。', '⭐')}</section></div>`; }


// 收银员账号由管理员创建并绑定柜台；容量与权限以 Java 的再次校验为准。
async function viewCashiers() {
  const data = await api('/cashiers'); state.cashierData = data;
  const rows = array(data.cashiers), counters = array(data.counters), limit = num(data.limit) || 4;
  return heading('收银员管理', '创建门店收银账号，安排负责的收银台，让每笔会员提交都有人接待。', `<button class="btn outline" data-action="refresh">${icon('refresh')}刷新</button><button class="btn primary" data-action="cashier-new" ${rows.length >= limit ? 'disabled' : ''}>${icon('plus')}新增收银员</button>`, 'STORE TEAM / CASHIER MANAGEMENT') +
    `<div class="cashier-overview"><div><span>收银员账号</span><strong>${rows.length}<small> / ${limit} 人</small></strong></div><div><span>已启用</span><strong>${rows.filter(row => enabled(row.enabled)).length}<small> 人</small></strong></div><div><span>剩余名额</span><strong>${Math.max(0, limit - rows.length)}<small> 人</small></strong></div></div>
    <div class="callout section-gap">${icon('info')}<p>最多创建 ${limit} 个收银员账号，已停用账号也计入上限。新增时选择空闲柜台，保存后即可使用新账号登录。更换柜台或停用前，请先处理完该员工的待确认商品。</p></div>
    <section class="panel section-gap"><div class="panel-head"><div><h2>门店收银员</h2><p>会员注册入口只创建会员；收银员由管理员在这里添加。</p></div><span class="tag">${rows.length} / ${limit} 人</span></div><div class="cashier-card-grid">${rows.map(row => {
      const counter = counters.find(c => num(c.counterNo) === num(row.counterNo));
      return `<article class="cashier-card"><header><div class="avatar">${esc((row.displayName || row.username).slice(0,1))}</div><div><h3>${esc(row.displayName)}</h3><small class="mono">${esc(row.username)}</small></div><span class="tag ${enabled(row.enabled) ? '' : 'gray'}">${enabled(row.enabled) ? '已启用' : '已停用'}</span></header><div class="cashier-station"><span>负责收银台</span><strong>${row.counterNo ? `${integer(row.counterNo)} 号收银台` : '尚未安排'}</strong><small>${counter ? esc(statusNames[counter.status] || counter.status || '') : '请安排柜台'}${num(counter?.waitingCount) ? ` · ${integer(counter.waitingCount)} 笔待确认` : ''}</small></div><footer><button class="btn outline small" data-action="cashier-counter" data-id="${num(row.id)}">${icon('edit')}安排收银台</button><button class="btn small ${enabled(row.enabled) ? 'outline' : 'primary'}" data-action="cashier-toggle" data-id="${num(row.id)}">${enabled(row.enabled) ? '停用账号' : '启用账号'}</button></footer></article>`;
    }).join('') || empty('暂无收银员', '点击新增收银员，为门店安排第一位员工。')}</div></section>
    <div class="cashier-page-links"><button class="btn outline" data-action="navigate" data-page="queue">查看排队管理 ${icon('arrow')}</button><button class="btn link" data-action="navigate" data-page="settings">调整营业收银台数量</button></div>`;
}
async function cashierModal(id) {
  const data = await api('/cashiers'); state.cashierData = data;
  const row = array(data.cashiers).find(c => num(c.id) === num(id));
  if (id && !row) throw new Error('该收银员不存在，请刷新名单');
  if (!id && array(data.cashiers).length >= (num(data.limit) || 4)) throw new Error('收银员账号已达到 4 人上限');
  const counters = array(data.counters).filter(c => c.cashierId == null || num(c.cashierId) === num(id));
  if (!counters.length) throw new Error('暂无空闲收银台，请先检查柜台安排');
  const formId = id ? 'cashier-counter-form' : 'cashier-form';
  showModal(id ? `安排 ${row.displayName} 的收银台` : '新增收银员', `<form id="${formId}" data-id="${num(id)}" class="form-stack">${id ? '' : `<div class="form-grid"><label class="field"><span>登录账号</span><input name="username" required pattern="[A-Za-z0-9_]{3,30}" minlength="3" maxlength="30" autocomplete="off" placeholder="例如 cashier3"><small>3～30 位字母、数字或下划线</small></label><label class="field"><span>员工姓名</span><input name="displayName" required maxlength="60" placeholder="请输入员工姓名"></label></div><label class="field"><span>登录密码</span><input name="password" type="password" required minlength="8" maxlength="60" autocomplete="new-password" placeholder="至少 8 位，交给该员工本人使用"></label>`}<label class="field"><span>负责收银台</span><select name="counterNo" required>${counters.map(c => `<option value="${num(c.counterNo)}" ${num(c.counterNo) === num(row?.counterNo) ? 'selected' : ''}>${integer(c.counterNo)} 号收银台${num(c.cashierId) === num(id) && id ? '（当前）' : '（空闲）'}</option>`).join('')}</select><small>安排后将开放对应编号的收银台；已有员工的柜台不会被覆盖。</small></label><div class="callout">${icon('shield')}<p>${id ? '有顾客正在等待时不能调岗，请先完成或取消相关提交。' : '保存后，员工使用这个账号和密码登录，即可进入自己的收银工作台。'}</p></div></form>`, `<button class="btn outline" data-action="modal-close">取消</button><button class="btn primary" type="submit" form="${formId}">${id ? '保存安排' : '创建并安排收银台'}</button>`);
}

const refundStatusNames = {NONE: '未申请退款', PENDING: '退款待审核', APPROVED: '退款已批准', REJECTED: '退款申请被拒绝'};
function refundTag(order) { return order.refundStatus && order.refundStatus !== 'NONE' ? `<span class="tag ${order.refundStatus === 'PENDING' ? 'orange' : order.refundStatus === 'REJECTED' ? 'gray' : ''}">${esc(refundStatusNames[order.refundStatus] || order.refundStatus)}</span>` : ''; }
function refundActions(order) {
  if (order.legacyDemoOrder || order.status !== 'PAID') return '';
  if (isAdmin() && order.refundStatus === 'PENDING') return `<button class="btn primary small" data-action="refund-review" data-id="${num(order.id)}">审核退款</button>`;
  if (isMember() && order.refundStatus !== 'PENDING') return `<button class="btn outline small" data-action="refund-request" data-id="${num(order.id)}">${order.refundStatus === 'REJECTED' ? '重新申请退款' : '申请退款'}</button>`;
  return '';
}
function refundPanel(order) {
  if (!order.refundStatus || order.refundStatus === 'NONE') return '';
  return `<section class="refund-progress"><div>${refundTag(order)}<small>${dateTime(order.refundRequestedAt)}</small></div><p><strong>申请原因：</strong>${esc(order.refundReason)}</p>${order.refundStatus === 'PENDING' ? '<p>已提交至老板审核，审核通过前订单和会员权益保持不变。</p>' : `<p><strong>${order.refundStatus === 'REJECTED' ? '拒绝原因' : '审核说明'}：</strong>${esc(order.refundReviewNote || '老板已批准整单退款')}</p><small>处理时间：${dateTime(order.refundReviewedAt)}</small>`}</section>`;
}
async function refundRequestModal(id) {
  if (!isMember()) throw new Error('仅订单所属会员可以申请退款');
  const order = await api(`/orders/${id}`);
  if (order.status !== 'PAID' || order.legacyDemoOrder || order.refundStatus === 'PENDING') throw new Error('这笔订单当前不能重复申请退款，请刷新查看状态');
  showModal('申请整单退款', `<form id="refund-request-form" data-id="${num(id)}" class="form-stack"><div class="refund-order-summary"><strong>${esc(order.orderNo)}</strong><span>申请退款金额 ¥${money(order.payableAmount)}</span></div><div class="callout">${icon('info')}<p>申请将提交给老板审核。批准后整单退款，并撤回本单积分和累计消费；审核前订单保持已支付。</p></div><label class="field"><span>申请原因</span><textarea name="reason" required maxlength="200" placeholder="请说明申请整单退款的原因，最多 200 字"></textarea></label></form>`, '<button class="btn outline" data-action="modal-close">暂不申请</button><button class="btn primary" type="submit" form="refund-request-form">提交给老板审核</button>');
}
async function refundReviewModal(id) {
  if (!isAdmin()) throw new Error('仅老板可以审核退款');
  const order = await api(`/orders/${id}`);
  if (order.status !== 'PAID' || order.refundStatus !== 'PENDING' || order.legacyDemoOrder) throw new Error('这笔退款申请已处理，请刷新查看结果');
  showModal('审核会员退款申请', `<form id="refund-review-form" data-id="${num(id)}" class="form-stack"><div class="refund-order-summary"><strong>${esc(order.memberName || '会员')} · ${esc(order.orderNo)}</strong><span>整单退款金额 ¥${money(order.payableAmount)}</span></div><p>${esc(array(order.items).map(i => `${i.productName} × ${i.quantity}`).join('、'))}</p>${refundPanel(order)}<label class="field"><span>处理决定</span><select name="decision"><option value="approve">批准整单退款</option><option value="reject">拒绝退款申请</option></select></label><label class="field"><span>处理说明（拒绝时必填）</span><textarea name="reason" maxlength="200" placeholder="说明审核结果，会员与原收银员都可以查看"></textarea></label><div class="callout orange">${icon('info')}<p>批准后将整单商品退回库存，并撤回积分和累计净消费。请先确认退货情况，再提交审核决定。</p></div></form>`, '<button class="btn outline" data-action="modal-close">稍后处理</button><button class="btn primary" type="submit" form="refund-review-form">确认处理决定</button>', true);
}
async function viewRefunds() {
  state.orders = array(await api('/refunds'));
  const pending = state.orders.filter(o => o.refundStatus === 'PENDING'), processed = state.orders.filter(o => ['APPROVED','REJECTED'].includes(o.refundStatus));
  return heading('会员退款审核', '会员提交退款原因，由老板核对后决定是否批准。收银员可以查看处理结果。', `<button class="btn outline" data-action="refresh">${icon('refresh')}刷新申请</button>`, 'AFTER SALES / REFUND REQUESTS') + `<section class="panel"><div class="panel-head"><div><h2>等待审核</h2><p>批准前不会改变库存、积分或销售金额</p></div><span class="tag orange">${pending.length} 笔</span></div>${pending.length ? staffOrderRows(pending) : empty('暂无待审核申请', '会员从“我的订单”申请退款后，会显示在这里。', '🧾')}</section><section class="panel section-gap"><div class="panel-head"><h2>已处理申请</h2><span class="tag">${processed.length} 笔</span></div>${processed.length ? staffOrderRows(processed) : empty('暂无处理记录', '已批准或拒绝的申请将在这里保留。')}</section>`;
}

let modalReturnFocus = null;
function showModal(title, body, footer = '', wide = false, subtitle = '') {
  if (!$('#modal-root').children.length) modalReturnFocus = document.activeElement;
  document.body.classList.add('modal-open');
  $('#modal-root').innerHTML = `<div class="modal-backdrop"><section class="modal${wide ? ' wide' : ''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2>${subtitle ? `<p>${esc(subtitle)}</p>` : ''}</div><button class="icon-btn" data-action="modal-close" aria-label="关闭弹窗">${icon('close')}</button></header><div class="modal-body" id="modal-body">${body}</div>${footer ? `<footer class="modal-foot">${footer}</footer>` : ''}</section></div>`;
  setTimeout(() => $('.modal-body input:not([readonly]), .modal-body select, .modal-body textarea, .modal-foot button, .modal button')?.focus(), 50);
}
function closeModal() {
  $('#modal-root').innerHTML = ''; state.modalData = null;
  document.body.classList.remove('modal-open');
  if (modalReturnFocus?.isConnected) modalReturnFocus.focus();
  modalReturnFocus = null;
}
function modalError(message) { const body = $('#modal-body'); if (!body) return; $('.modal-error', body)?.remove(); const element = document.createElement('div'); element.className = 'modal-error'; element.textContent = message; body.prepend(element); element.scrollIntoView({ block: 'nearest' }); }
function confirmModal(title, message, action, id, label = '确认操作', danger = false) { showModal(title, `<div class="confirm-body"><div class="confirm-icon">${danger ? '🧾' : '💠'}</div><h3>${esc(title)}</h3><p>${esc(message)}</p></div>`, `<button class="btn outline" data-action="modal-close">再想一想</button><button class="btn ${danger ? 'danger' : 'primary'}" data-action="${action}" data-id="${num(id)}">${esc(label)}</button>`); }
function productModal(id) {
  const product = state.products.find(item => num(item.id) === num(id)) || {};
  showModal(id ? '编辑设备资料' : '新增数码设备', `<form id="product-form" data-id="${num(id)}"><div class="form-grid single-mobile"><label class="field"><span>商品名称</span><input name="name" required maxlength="100" value="${esc(product.name)}" placeholder="例如：轻薄笔记本 Air 14"></label><label class="field"><span>商品编号 SKU</span><input name="sku" required maxlength="40" value="${esc(product.sku)}" placeholder="例如：LAPTOP-001"></label><label class="field"><span>商品分类</span><select name="categoryId" required><option value="">请选择分类</option>${state.categories.map(category => `<option value="${num(category.id)}" ${num(category.id) === num(product.categoryId) ? 'selected' : ''}>${esc(category.name)}</option>`).join('')}</select></label><label class="field"><span>商品单价（元）</span><input name="price" type="number" min="0.01" max="9999999.99" step="0.01" required value="${product.price === undefined ? '' : money(product.price)}"></label><label class="field"><span>${id ? '当前库存（通过采购入库调整）' : '初始库存'}</span><input name="stock" type="number" min="0" max="1000000" step="1" required value="${num(product.stock)}" ${id ? 'readonly' : ''}></label><label class="field"><span>低库存提醒线</span><input name="lowStockThreshold" type="number" min="0" max="1000000" step="1" required value="${product.lowStockThreshold === undefined ? 5 : num(product.lowStockThreshold)}"></label><label class="field"><span>商品图标 Emoji</span><input name="emoji" maxlength="16" value="${esc(product.emoji || '📦')}" placeholder="📱 / 💻 / ⌚ / 🖥️"></label><label class="field"><span>销售状态</span><select name="onSale"><option value="true" ${!id || enabled(product.onSale) ? 'selected' : ''}>上架销售</option><option value="false" ${id && !enabled(product.onSale) ? 'selected' : ''}>暂不上架</option></select></label><label class="field span2"><span>商品介绍</span><textarea name="description" maxlength="500" placeholder="填写品牌型号、内存、容量、尺寸等主要参数…">${esc(product.description)}</textarea></label></div></form>`, '<button class="btn outline" data-action="modal-close">取消</button><button class="btn primary" type="submit" form="product-form">保存商品</button>', false, id ? '库存通过采购、销售和退款流转，编辑资料不会直接覆盖库存。' : '价格、库存和分类会在保存时再次验证。');
}
async function categoryModal() { state.categories = array(await api('/categories')); showModal('整理门店分类', `<form id="category-form" class="toolbar" style="margin-bottom:12px"><input name="name" placeholder="输入新分类名称" required maxlength="60" style="flex:1"><button class="btn primary" type="submit">${icon('plus')}新增</button></form><div>${state.categories.map(category => `<div class="list-line"><div class="grow"><strong>${esc(category.name)}</strong></div><button class="btn tiny" data-action="category-edit" data-id="${num(category.id)}">重命名</button><button class="icon-btn danger" data-action="category-delete" data-id="${num(category.id)}" aria-label="删除分类">${icon('trash')}</button></div>`).join('') || empty('先创建一个分类', '例如：智能手机、笔记本电脑、智能穿戴、显卡配件。', '💠')}</div>`, '<button class="btn primary" data-action="categories-done">完成整理</button>'); }
